import asyncio
from backend.ext_api.api_ratelimiter import RateLimiter
import httpx
import pytest

from backend.ext_api import (
    APIRouterError,
    APIStatusError,
    APITimeout,
    APIRouterTemplate,
)


class DummyAPI(APIRouterTemplate):
    async def _auth(self):
        self.default_headers["Authorization"] = "Bearer test-token"


class OAuthAPI(APIRouterTemplate):
    async def _auth(self):
        self.default_headers["Authorization"] = "Bearer oauth-token"

# The following tests are generated by Github Copilot for generic testing of the core fucntionalities of the API template. 
# They are not exhaustive and may not cover all edge cases.

def _make_async_client(handler):
    return httpx.AsyncClient(
        base_url="https://example.com",
        headers={"Accept": "application/json"},
        timeout=1.0,
        transport=httpx.MockTransport(handler),
    )


def test_context_manager_initializes_client_and_syncs_headers():
    api = DummyAPI("test site","https://example.com", headers={"X-Test": "one"}, timeout=1.0)

    async def _run():
        async with api:
            assert api.client is not None
            assert api.client.headers["X-Test"] == "one"
            api.default_headers["Authorization"] = "Bearer updated-token"
            api.sync_default_header_with_httpx_client()
            assert api.client.headers["Authorization"] == "Bearer updated-token"

    asyncio.run(_run())


def test_sync_default_headers_updates_live_client():
    api = DummyAPI(
        "test site",
        "https://example.com",
        headers={"Accept": "application/json"},
        timeout=1.0,
    )

    async def _run():
        async with api:
            api.default_headers["X-Trace-Id"] = "abc123"
            api.sync_default_header_with_httpx_client()
            assert api.client.headers["X-Trace-Id"] == "abc123"

    asyncio.run(_run())


def test_request_without_client_raises_api_router_error():
    api = DummyAPI("test site","https://example.com", timeout=1.0)

    async def _run():
        with pytest.raises(APIRouterError):
            await api._request("GET", "/health")

    asyncio.run(_run())


def test_oauth_auth_runs_before_request_and_header_override_is_used():
    api = OAuthAPI(
        "test site",
        "https://example.com",
        headers={"X-Trace": "base"},
        timeout=1.0,
        oauth=True,
    )

    async def handler(request):
        assert request.headers["Authorization"] == "Bearer oauth-token"
        assert request.headers["X-Trace"] == "override"
        assert request.url == "https://example.com/health?limit=10"
        return httpx.Response(200, json={"status": "ok"})

    async def _run():
        async with api:
            api.client = _make_async_client(handler)
            api.default_headers["X-Trace"] = "base"
            result = await api._request(
                "GET",
                "/health",
                params={"limit": 10},
                headers_override={"X-Trace": "override"},
            )
            assert result == {"status": "ok"}

    asyncio.run(_run())


def test_http_status_error_is_wrapped_in_api_status_error():
    api = DummyAPI("test site","https://example.com", timeout=1.0)

    async def handler(request):
        return httpx.Response(500, json={"error": "bad"}, request=request)

    async def _run():
        async with api:
            api.client = _make_async_client(handler)
            with pytest.raises(APIStatusError) as exc_info:
                await api._request("GET", "/status")

        assert exc_info.value.status_code == 500
        assert exc_info.value.base_url == "https://example.com"
        assert exc_info.value.endpoint == "/status"

    asyncio.run(_run())


def test_timeout_error_raises_api_timeout():
    api = DummyAPI("test site","https://example.com", timeout=0.1)

    async def handler(request):
        raise httpx.ReadTimeout("timed out")

    async def _run():
        async with api:
            api.client = _make_async_client(handler)
            with pytest.raises(APITimeout):
                await api._request("GET", "/slow")

    asyncio.run(_run())


def test_request_error_raises_api_router_error():
    api = DummyAPI("test site","https://example.com", timeout=1.0)

    async def handler(request):
        raise httpx.ConnectError("connection failed")

    async def _run():
        async with api:
            api.client = _make_async_client(handler)
            with pytest.raises(APIRouterError):
                await api._request("GET", "/fail")

    asyncio.run(_run())

